import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"侧信道直觉","description":"","frontmatter":{"title":"侧信道直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/side-channel.md","filePath":"cs/side-channel.md","lastUpdated":1789023840000}'),h={name:"cs/side-channel.md"};function E(A,a,_,m,u,T){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="侧信道直觉" tabindex="-1">侧信道直觉 <a class="header-anchor" href="#侧信道直觉" aria-label="Permalink to &quot;侧信道直觉&quot;">​</a></h1><div class="epigraph"><p>规格上的隔离保证的是状态与系统调用；时间、缓存、功耗仍可能把密钥变成可测的差异。</p><footer>—— 据 Kocher 对计时；Anderson 对侧信道作为威胁模型扩展的整理</footer></div><p><a href="/cs/isolation-sandbox">上一课</a>把不可信代码关进盒子。本课不重列容器机制。缺口是：威胁模型若只写「读不了别人的页」，会漏掉<strong>非规格输出</strong>：运行时间、缓存命中、分支预测、电磁。它们不破坏 2PC，也不需要越界写，就能伤害 CIA 的 C。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>密码实现若按密钥位走不同时间或不同缓存线，观察者即使不能读内存，也能推断位。<a href="/cs/privilege-rings">特权级</a>与页表不把这些当成通道。缺口不是提供测量与还原密钥的步骤，而是把侧信道标进模型：共享 CPU 的租户、本机恶意进程、甚至远程可测延迟。防御是常数时间实现、隔离共享资源、降低分辨率，而不是再加一把 ACL。</p><p><span class="marginnote">本课不描述具体微结构攻击的操作序列，不给实验配方。只需：逻辑正确的 AES 仍可能在时间上泄漏；对抗要改实现与调度，不只改密钥长度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把「允许观察什么」写进<a href="/cs/threat-model">威胁模型</a>。实现层：无密钥依赖的分支与访存（常数时间密码）。系统层：关超线程共用、刷新、分区缓存、减少计时器精度。协议层：避免根据秘密走明显不同的往返次数。本课不宣称某一层单独够用。</p>',8)),(e(),s(c,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E9%A1%B5%E8%A1%A8%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20LEAK%5B%22%E6%97%B6%E9%97%B4%20%2F%20%E7%BC%93%E5%AD%98%20%2F%20%E5%8A%9F%E8%80%97%22%5D%0A%20%20LEAK%20--%3E%20TM%5B%22%E6%89%A9%E5%B1%95%E5%A8%81%E8%83%81%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20TM%20--%3E%20TLS%5B%22%E5%90%8E%E8%AF%BE%3A%20TLS%20%E6%8F%A1%E6%89%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>侧信道把「盒子」从逻辑集合变成物理共享。云上多租户使远程计时也进入模型。与缓冲区溢出对照：那是完整性破坏控制流；这里往往是保密失败而控制流仍「正确」。因此测试功能正确不够，还要测实现是否密钥无关。</p><p>共享末级缓存把「不同进程」重新连成可测通道，逻辑页表看不见。调度与关超线程是系统层补丁，不是 ACL。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成硬件漏洞利用教程。也不要把所有性能抖动都叫侧信道：必须有与秘密相关的差异。物理接触下的功耗、探针是另一类实验室模型，主干只要求意识到存在。</p><p>远程计时的分辨率低于本机缓存探测，威胁模型要写清观察者位置。后课默认：即使沙箱正确，密钥操作仍应常数时间；网络上的保密会话要在 TLS 握手里绑密钥，而不是只靠「对方在盒子外」。</p><p>实现「功能测试通过」不够。密钥相关的时间差是规格外的输出，必须单独列入测试与代码审查的对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>后课默认：密钥操作按常数时间写，TLS 不管端点缓存。</p></li><li><p>常数时间是实现约束：分支与访存不得依赖秘密。本课不给测量还原步骤。</p></li><li><p>后课 TLS 在链路上绑会话键，仍不管端点微结构。</p></li><li><p>沙箱管逻辑边界；侧信道把时间与微结构标进威胁模型。</p></li><li><p>防御：常数时间、资源隔离、降分辨率。</p></li><li><p>开放网上如何协商并认证会话键，是 TLS 握手课。</p></li><li><p>出处：Kocher, 1996（计时作为一类通道的名字）；Anderson, <em>Security Engineering</em>。</p></li></ul>',9))])}const B=l(h,[["render",E]]);export{S as __pageData,B as default};
